PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE directional_skill_pit_exploratory_result (
            group_name TEXT PRIMARY KEY, selection_rule TEXT, role TEXT,
            n_traders_input INTEGER, n_traders_surviving INTEGER, n_positions INTEGER,
            point_gap REAL, ci_lo REAL, ci_hi REAL, mde_half_width REAL,
            is_exploratory INTEGER, is_preregistered INTEGER,
            produced_as_byproduct_of TEXT, asymmetry_note TEXT,
            membership_verified_matches_original INTEGER, nondeterminism_note TEXT,
            redevrived_point_gap REAL, redevrived_ci_lo REAL, redevrived_ci_hi REAL,
            redevrived_n_positions INTEGER, redevrived_n_traders_surviving INTEGER,
            spec_version TEXT, seed INTEGER, t_split TEXT,
            generated_at TEXT, generator_commit TEXT,
            source_pit_pool_json TEXT, source_power_estimate_json TEXT);
INSERT INTO directional_skill_pit_exploratory_result VALUES('raw_cohort','raw','cohort',711,711,10453,0.00899771134083471313,-0.0126809822550556748,0.0290434441111681596,0.0208999999999999984,1,0,'clustered-bootstrap power estimate (Step 3, directional_skill_pit_power_estimate.py, first-repo 4feb97f) -- not a planned/pre-registered test','1B FINDING (see 2026-09-06-directional-skill-exploratory-custody.md): the cohort arm was drawn from an already post-split-survival-filtered list (Part B''s raw/bh_survivors, defined as skilled AND with >=1 post-split resolved position), while the placebo arm was matched on PRE-split profile only via match_control(), with no post-split-survival condition -- hence cohort measure_oos surviving rate is 100% by construction and placebo''s is ~52-56%. The two arms are NOT like-for-like as constructed. Not fixed here; reported for any reader of these figures.',1,NULL,NULL,NULL,NULL,NULL,NULL,'DIRSKILL-PIT-EXPLORATORY-2026-09-06-v1',42,'2026-04-01 00:00:00','2026-09-06T16:31:16.972891+00:00','4feb97ff9ec896f55f852622efc666b288e0babf','data/characterizations/directional_skill_pit_legal_pool_20260906T160303Z.json','data/characterizations/directional_skill_pit_power_estimate_20260906T160818Z.json');
INSERT INTO directional_skill_pit_exploratory_result VALUES('raw_placebo','raw','placebo',711,368,5841,0.00986869702495585254,-0.0154830198126575998,0.0358289360201658399,0.0257000000000000006,1,0,'clustered-bootstrap power estimate (Step 3, directional_skill_pit_power_estimate.py, first-repo 4feb97f) -- not a planned/pre-registered test','1B FINDING (see 2026-09-06-directional-skill-exploratory-custody.md): the cohort arm was drawn from an already post-split-survival-filtered list (Part B''s raw/bh_survivors, defined as skilled AND with >=1 post-split resolved position), while the placebo arm was matched on PRE-split profile only via match_control(), with no post-split-survival condition -- hence cohort measure_oos surviving rate is 100% by construction and placebo''s is ~52-56%. The two arms are NOT like-for-like as constructed. Not fixed here; reported for any reader of these figures.',0,'DISCOVERED 2026-09-06 (this custody pass): match_control() (trader_skill_metric_v2f.py) does not fully determine its output from its `seed` parameter alone. cohort_traders and elig_traders are Python sets; match_control() calls list() on them before shuffling/iterating, and CPython''s set iteration order for strings depends on the process-level hash seed (PYTHONHASHSEED), which is randomized fresh per process by default and is not fixed by this function''s seed argument. Re-running match_control() with the identical seed=42 in a separate process (this script) reproduced the COHORT membership exactly (cohort membership does not depend on match_control at all -- it is Part B''s already-persisted survivor list) but did NOT reproduce the PLACEBO membership or its resulting point_gap/CI from the committed Step 3 artifact. This affects every prior placebo constructed via match_control(), including the 2026-08-15 result-of-record placebo and the 2026-09-06 Step 3 placebo -- neither is exactly reconstructable from its recorded seed alone. Not fixed here, per this task''s scope; reported as a finding.',0.0131060477575950518,-0.0132962419650145043,0.0388720449450414493,5733,371,'DIRSKILL-PIT-EXPLORATORY-2026-09-06-v1',42,'2026-04-01 00:00:00','2026-09-06T16:31:16.972891+00:00','4feb97ff9ec896f55f852622efc666b288e0babf','data/characterizations/directional_skill_pit_legal_pool_20260906T160303Z.json','data/characterizations/directional_skill_pit_power_estimate_20260906T160818Z.json');
INSERT INTO directional_skill_pit_exploratory_result VALUES('bh_cohort','bh','cohort',504,504,7733,0.0028532391996697326,-0.0236628644948351646,0.0258747849896818204,0.0247999999999999991,1,0,'clustered-bootstrap power estimate (Step 3, directional_skill_pit_power_estimate.py, first-repo 4feb97f) -- not a planned/pre-registered test','1B FINDING (see 2026-09-06-directional-skill-exploratory-custody.md): the cohort arm was drawn from an already post-split-survival-filtered list (Part B''s raw/bh_survivors, defined as skilled AND with >=1 post-split resolved position), while the placebo arm was matched on PRE-split profile only via match_control(), with no post-split-survival condition -- hence cohort measure_oos surviving rate is 100% by construction and placebo''s is ~52-56%. The two arms are NOT like-for-like as constructed. Not fixed here; reported for any reader of these figures.',1,NULL,NULL,NULL,NULL,NULL,NULL,'DIRSKILL-PIT-EXPLORATORY-2026-09-06-v1',42,'2026-04-01 00:00:00','2026-09-06T16:31:16.972891+00:00','4feb97ff9ec896f55f852622efc666b288e0babf','data/characterizations/directional_skill_pit_legal_pool_20260906T160303Z.json','data/characterizations/directional_skill_pit_power_estimate_20260906T160818Z.json');
INSERT INTO directional_skill_pit_exploratory_result VALUES('bh_placebo','bh','placebo',504,280,4478,0.0160777147772828143,-0.0132890638126057954,0.0445714036792700732,0.0288999999999999986,1,0,'clustered-bootstrap power estimate (Step 3, directional_skill_pit_power_estimate.py, first-repo 4feb97f) -- not a planned/pre-registered test','1B FINDING (see 2026-09-06-directional-skill-exploratory-custody.md): the cohort arm was drawn from an already post-split-survival-filtered list (Part B''s raw/bh_survivors, defined as skilled AND with >=1 post-split resolved position), while the placebo arm was matched on PRE-split profile only via match_control(), with no post-split-survival condition -- hence cohort measure_oos surviving rate is 100% by construction and placebo''s is ~52-56%. The two arms are NOT like-for-like as constructed. Not fixed here; reported for any reader of these figures.',0,'DISCOVERED 2026-09-06 (this custody pass): match_control() (trader_skill_metric_v2f.py) does not fully determine its output from its `seed` parameter alone. cohort_traders and elig_traders are Python sets; match_control() calls list() on them before shuffling/iterating, and CPython''s set iteration order for strings depends on the process-level hash seed (PYTHONHASHSEED), which is randomized fresh per process by default and is not fixed by this function''s seed argument. Re-running match_control() with the identical seed=42 in a separate process (this script) reproduced the COHORT membership exactly (cohort membership does not depend on match_control at all -- it is Part B''s already-persisted survivor list) but did NOT reproduce the PLACEBO membership or its resulting point_gap/CI from the committed Step 3 artifact. This affects every prior placebo constructed via match_control(), including the 2026-08-15 result-of-record placebo and the 2026-09-06 Step 3 placebo -- neither is exactly reconstructable from its recorded seed alone. Not fixed here, per this task''s scope; reported as a finding.',0.0143461093319688925,-0.0156483299613607504,0.0447015287521994181,4390,284,'DIRSKILL-PIT-EXPLORATORY-2026-09-06-v1',42,'2026-04-01 00:00:00','2026-09-06T16:31:16.972891+00:00','4feb97ff9ec896f55f852622efc666b288e0babf','data/characterizations/directional_skill_pit_legal_pool_20260906T160303Z.json','data/characterizations/directional_skill_pit_power_estimate_20260906T160818Z.json');
COMMIT;
